// Line ids st.<story>x<n> (✎ corrections, her recordings). Words and quiz lines are study aids, not recorded.
const row = ([ar, say, en, uk]) => ({ ar, say, en, uk });
export const LEVELS = ["easy", "A1", "A2"];
export const STORIES = RAW.map(s => ({
  ...s,
  check: true,
  text: s.text.map((l, i) => ({ ...row(l), id: `st.${s.id}x${i}`, story: s.id, check: true })),
  words: s.words.map(w => ({ ...row(w), check: true })),
  quiz: s.quiz.map(q => ({ ...row(q), answer: q[4] })),
}));
export const STORY_LINES = STORIES.flatMap(s => s.text);
